import { ref } from 'vue'
import AppearanceControl from '../components/AppearanceControl.vue'

const cep = ref('')
const cepMessage = ref('')
const contactSubmitted = ref(false)

function normalizeCep(value: string) { return value.replace(/\D/g, '').slice(0, 8) }
function formatCep() { cep.value = normalizeCep(cep.value).replace(/^(\d{5})(\d)/, '$1-$2') }
function findEstablishments() {
  cepMessage.value = normalizeCep(cep.value).length === 8
    ? 'A busca por estabelecimentos está sendo preparada para esta primeira versão.'
    : 'Informe um CEP com 8 dígitos para continuar.'
}
function goToContact() { document.querySelector('#contact')?.scrollIntoView({ behavior: 'smooth' }) }
function submitContact() { contactSubmitted.value = true }
